sys_ws_operation.script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var body = request.body.data;
    var prompt       = (body.prompt       || '').toString().trim();
    var model        = (body.model        || '').toString().trim();
    var systemPrompt = (body.system_prompt|| '').toString().trim();
    var prefill      = (body.prefill      || '').toString().trim();
    var stopRaw      = (body.stop_sequences || '').toString().trim();
    var sessionId    = (body.session_id   || '').toString().trim();

    if (!prompt) {
        response.setStatus(400);
        response.setBody({ error: 'Prompt cannot be empty.' });
        return;
    }
    if (!sessionId) {
        response.setStatus(400);
        response.setBody({ error: 'session_id is required.' });
        return;
    }

    // Parse stop sequences from comma-separated string
    var stopSeqs = [];
    if (stopRaw) {
        var parts = stopRaw.split(',');
        for (var i = 0; i < parts.length; i++) {
            var s = parts[i].trim();
            if (s) { stopSeqs.push(s); }
        }
    }

    // Load conversation history from GlideRecord (sys_user_session or a custom table).
    // We use a Glide Cache (gs.getSessionObject) scoped to the REST request session.
    // Since REST calls are stateless, history is persisted in a sys_cache record keyed by sessionId.
    var historyKey = 'x_146833_claudec_0.history.' + sessionId;
    var historyJson = GlideCacheManager.get(historyKey);
    var history = [];
    if (historyJson) {
        try { history = JSON.parse(historyJson); } catch(e) { history = []; }
    }

    // Append new user message
    history.push({ role: 'user', content: prompt });

    var connector = new x_146833_claudec_0.ClaudeConnector();
    var result = connector.chat(history, {
        model:          model,
        system_prompt:  systemPrompt,
        prefill:        prefill,
        stop_sequences: stopSeqs
    });

    if (!result.success) {
        response.setStatus(502);
        response.setBody({ error: result.error });
        return;
    }

    // Persist assistant reply to history
    history.push({ role: 'assistant', content: result.text });
    GlideCacheManager.put(historyKey, JSON.stringify(history));

    response.setStatus(200);
    response.setBody({
        text:         result.text,
        model:        result.model,
        inputTokens:  result.inputTokens,
        outputTokens: result.outputTokens,
        totalTokens:  result.inputTokens + result.outputTokens
    });

})(request, response);
